<script setup lang="ts">
import type {Row} from '~/utils/resources'
const rows=ref<Row[]>([]),csv=ref(''),busy=ref(false),error=ref(''),message=ref('')
async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){csv.value=await f.text();rows.value=[];message.value=''}}
async function preview(){busy.value=true;error.value='';try{const result=await useApi()<{rows:Row[]}>('/reconcile/preview',{method:'POST',body:{csv:csv.value}});rows.value=result.rows.map(r=>({...r,selected:r.autoInvoiceId||''}))}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
const selected=computed(()=>rows.value.filter(r=>r.selected&&!r.error))
async function confirm(){busy.value=true;error.value='';try{const result=await useApi()<Row>('/reconcile/confirm',{method:'POST',body:{matches:selected.value.map(r=>({invoiceId:r.selected,idempotencyKey:r.idempotencyKey,amount:r.amount,date:r.date,description:r.description}))}});message.value=`${result.recorded} payments recorded.`;rows.value=[];csv.value='';const failed=result.results.filter((r:Row)=>!r.ok);if(failed.length)error.value=failed.map((r:Row)=>r.error).join('; ')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="page"><div class="page-head"><div><h1>Bank reconciliation</h1><p>Match incoming payments with outstanding invoices.</p></div><UButton to="/samples/bank-statement.csv" external download variant="outline">Download sample</UButton></div><UCard><UAlert v-if="error" :title="error" color="error" class="mb-4"/><UAlert v-if="message" :title="message" color="success" class="mb-4"/><label for="bank-file" class="block text-sm font-medium mb-3">Bank statement CSV</label><input id="bank-file" type="file" accept=".csv,text/csv" class="block w-full text-sm mb-5" @change="file"/><UButton :disabled="!csv" :loading="busy" @click="preview">Find matches</UButton><div v-if="rows.length" class="mt-6"><div class="flex justify-between mb-4"><p class="text-sm text-muted">Review suggested matches before recording.</p><UButton :loading="busy" :disabled="!selected.length" @click="confirm">Record {{selected.length}} payments</UButton></div><div v-for="r in rows" :key="r.row" class="grid md:grid-cols-3 gap-4 border-t border-default py-4 text-sm"><div><p class="font-medium">{{r.description}}</p><p class="text-muted">{{date(r.date)}} · {{money(r.amount)}}</p></div><div><UBadge :color="r.error?'error':r.autoInvoiceId?'success':'warning'" variant="subtle">{{r.error?'Invalid':r.autoInvoiceId?'Matched':'Review'}}</UBadge><p v-if="r.error" class="text-error text-xs mt-2">{{r.error}}</p></div><USelect v-if="!r.error" v-model="r.selected" :items="[{label:'Skip this row',value:''},...r.candidates.map((c:Row)=>({label:`${c.number} · ${c.customerName} (${c.score})`,value:c.invoiceId}))]" aria-label="Match invoice"/></div></div></UCard></div></template>
